                    app_label, object_name = self.model_to_key(operation.field.remote_field.model)
                    if between.references_model(object_name, app_label):
                        return False
                    if getattr(operation.field.remote_field, "through", None):
                        app_label, object_name = self.model_to_key(operation.field.remote_field.through)
                        if between.references_model(object_name, app_label):
                            return False
            return [
                CreateModel(
                    self.name,
                    fields=self.fields + [(operation.name, operation.field)],
                    options=self.options,
                    bases=self.bases,
                    managers=self.managers,
                ),
            ]
        if isinstance(operation, AlterField):
            return [
                CreateModel(
                    self.name,
                    fields=[
                        (n, operation.field if n == operation.name else v)
                        for n, v in self.fields
                    ],
                    options=self.options,
                    bases=self.bases,
                    managers=self.managers,
                ),
            ]
        if isinstance(operation, RemoveField):
            return [
                CreateModel(
                    self.name,
                    fields=[
                        (n, v)
                        for n, v in self.fields
                        if n.lower() != operation.name_lower
                    ],
                    options=self.options,
                    bases=self.bases,
                    managers=self.managers,
                ),
            ]
        if isinstance(operation, RenameField):
            return [
                CreateModel(
                    self.name,
                    fields=[
                        (operation.new_name if n == operation.old_name else n, v)
                        for n, v in self.fields
                    ],
                    options=self.options,
                    bases=self.bases,
                    managers=self.managers,
                ),
            ]

    def reduce(self, operation, in_between, app_label=None):
        for handler in (
            self._handle_delete,
            self._handle_rename,
            self._handle_alter_options,
            lambda op: self._handle_field_operation(op, in_between),
        ):
