                to_field = to_state.apps.get_model(
                    *related_key
                )._meta.get_field(related_object.field.name)
                schema_editor.alter_field(
                    model,
                    related_object.field,
                    to_field,
                )
            fields = zip(old_model._meta.local_many_to_many, new_model._meta.local_many_to_many)
