    FileMetadata metadata = createMetadataForBlob(blob, blobKey, properties);
    FileMetadata existing = getDirectoryInList(list, blobKey);
    if (existing != null) list.remove(existing);
    list.add(metadata);
}

private void addDirectoryMetadata(CloudBlobDirectoryWrapper directory, ArrayList<FileMetadata> list) {
