private PartialListing list(String prefix, String delimiter,
      final int maxListingCount, final int maxListingDepth, String priorLastKey)
      throws IOException {
  try {
    checkContainer(ContainerAccessType.PureRead);
    String normalizedPrefix = normalizePrefix(prefix);
    Iterable<ListBlobItem> objects = getRootBlobs(normalizedPrefix);
    ArrayList<FileMetadata> fileMetadata = new ArrayList<FileMetadata>();
    processBlobItems(objects, fileMetadata, maxListingCount, maxListingDepth);
    return buildPartialListing(fileMetadata, normalizedPrefix);
  } catch (Exception e) {
    throw new AzureException(e);
  }
}

private String normalizePrefix(String prefix) {
  if (prefix.length() > 0 && !prefix.endsWith(PATH_DELIMITER)) {
    return prefix + PATH_DELIMITER;
  }
  return prefix;
}

private Iterable<ListBlobItem> getRootBlobs(String prefix) throws StorageException, URISyntaxException {
  if (prefix.equals("/")) {
    return listRootBlobs(true);
  } else {
    return listRootBlobs(prefix, true);
  }
}

private void processBlobItems(Iterable<ListBlobItem> objects, ArrayList<FileMetadata> fileMetadata,
      int maxListingCount, int maxListingDepth) throws Exception {
  for (ListBlobItem blobItem : objects) {
    if (maxListingCount > 0 && fileMetadata.size() >= maxListingCount) {
      break;
    }
    if (blobItem instanceof CloudBlockBlobWrapper || blobItem instanceof CloudPageBlobWrapper) {
      processBlobItem((CloudBlobWrapper) blobItem, fileMetadata);
    } else if (blobItem instanceof CloudBlobDirectoryWrapper) {
      processDirectoryItem((CloudBlobDirectoryWrapper) blobItem, fileMetadata, maxListingDepth);
    }
  }
}

private void processBlobItem(CloudBlobWrapper blob, ArrayList<FileMetadata> fileMetadata) throws Exception {
  BlobProperties properties = blob.getProperties();
  String blobKey = normalizeKey(blob);
  FileMetadata metadata;
  if (retrieveFolderAttribute(blob)) {
    metadata = new FileMetadata(blobKey,
        properties.getLastModified().getTime(),
        getPermissionStatus(blob),
        BlobMaterialization.Explicit);
  } else {
    metadata = new FileMetadata(
        blobKey,
        getDataLength(blob, properties),
        properties.getLastModified().getTime(),
        getPermissionStatus(blob));
  }
  FileMetadata existing = getDirectoryInList(fileMetadata, blobKey);
  if (existing != null) {
    fileMetadata.remove(existing);
  }
  fileMetadata.add(metadata);
}

private void processDirectoryItem(CloudBlobDirectoryWrapper directory, ArrayList<FileMetadata> fileMetadata,
      int maxListingDepth) throws Exception {
  String dirKey = normalizeKey(directory);
  if (dirKey.endsWith(PATH_DELIMITER)) {
    dirKey = dirKey.substring(0, dirKey.length() - 1);
  }
  FileMetadata directoryMetadata = new FileMetadata(dirKey, 0,
      defaultPermissionNoBlobMetadata(), BlobMaterialization.Implicit);
  if (getDirectoryInList(fileMetadata, dirKey) == null) {
    fileMetadata.add(directoryMetadata);
  }
  buildUpList(directory, fileMetadata, Integer.MAX_VALUE, maxListingDepth - 1);
}

private PartialListing buildPartialListing(ArrayList<FileMetadata> fileMetadata, String prefix) {
  priorLastKey = null;
  return new PartialListing(priorLastKey,
      fileMetadata.toArray(new FileMetadata[0]),
      fileMetadata.isEmpty() ? new String[0] : new String[] { prefix });
}

