private void rename(String srcKey, String dstKey, boolean acquireLease,
      SelfRenewingLease existingLease) throws IOException {
  try {
    validateRenameParameters(acquireLease, existingLease);
    checkContainer(ContainerAccessType.ReadThenWrite);
    CloudBlobWrapper srcBlob = getBlobReference(srcKey);
    validateSourceBlobExists(srcBlob);
    SelfRenewingLease lease = getLease(acquireLease, existingLease, srcBlob);
    CloudBlobWrapper dstBlob = getBlobReference(dstKey);
    copyBlob(srcBlob, dstBlob);
    waitForCopyToComplete(dstBlob, getInstrumentedContext());
    safeDelete(srcBlob, lease);
  } catch (Exception e) {
    throw new AzureException(e);
  }
}

private void validateRenameParameters(boolean acquireLease, SelfRenewingLease existingLease) throws IOException {
  if (acquireLease && existingLease != null) {
    throw new IOException("Cannot acquire new lease if one already exists.");
  }
}

private void validateSourceBlobExists(CloudBlobWrapper srcBlob) throws AzureException {
  if (!srcBlob.exists(getInstrumentedContext())) {
    throw new AzureException("Source blob " + srcBlob.getUri() + " does not exist.");
  }
}

private SelfRenewingLease getLease(boolean acquireLease, SelfRenewingLease existingLease, CloudBlobWrapper srcBlob) throws StorageException {
  if (acquireLease) {
    return srcBlob.acquireLease();
  } else if (existingLease != null) {
    return existingLease;
  }
  return null;
}

private void copyBlob(CloudBlobWrapper srcBlob, CloudBlobWrapper dstBlob) throws StorageException, URISyntaxException {
  URI srcUri = new URI(srcBlob.getUri().toASCIIString());
  try {
    dstBlob.startCopyFromBlob(srcUri, null, getInstrumentedContext());
  } catch (StorageException se) {
    if (se.getErrorCode().equals(StorageErrorCode.SERVER_BUSY.toString())) {
      retryCopyOnServerBusy(dstBlob, srcUri);
    } else {
      throw se;
    }
  }
}

private void retryCopyOnServerBusy(CloudBlobWrapper dstBlob, URI srcUri) throws StorageException {
  int copyBlobMinBackoff = sessionConfiguration.getInt(KEY_COPYBLOB_MIN_BACKOFF_INTERVAL,
      DEFAULT_COPYBLOB_MIN_BACKOFF_INTERVAL);
  int copyBlobMaxBackoff = sessionConfiguration.getInt(KEY_COPYBLOB_MAX_BACKOFF_INTERVAL,
      DEFAULT_COPYBLOB_MAX_BACKOFF_INTERVAL);
  int copyBlobDeltaBackoff = sessionConfiguration.getInt(KEY_COPYBLOB_BACKOFF_INTERVAL,
      DEFAULT_COPYBLOB_BACKOFF_INTERVAL);
  int copyBlobMaxRetries = sessionConfiguration.getInt(KEY_COPYBLOB_MAX_IO_RETRIES,
      DEFAULT_COPYBLOB_MAX_RETRY_ATTEMPTS);
  BlobRequestOptions options = new BlobRequestOptions();
  options.setRetryPolicyFactory(new RetryExponentialRetry(
      copyBlobMinBackoff, copyBlobDeltaBackoff, copyBlobMaxBackoff,
      copyBlobMaxRetries));
  dstBlob.startCopyFromBlob(srcUri, options, getInstrumentedContext());
}

