private FileMetadata retrieveMetadata(String key) throws IOException {
  try {
    checkContainer(ContainerAccessType.PureRead);
    if (LOG.isDebugEnabled()) LOG.debug("Retrieving metadata for " + key);
    if (checkContainer(ContainerAccessType.PureRead) == ContainerState.DoesntExist) {
      return null;
    }
    if (key.equals("/")) {
      return handleRootMetadata();
    }
    CloudBlobWrapper blob = getBlobReference(key);
    if (blob != null && blob.exists(getInstrumentedContext())) {
      return handleExistingBlob(blob);
    }
    return handlePotentialDirectory(key);
  } catch (Exception e) {
    throw new AzureException(e);
  }
}

private FileMetadata handleRootMetadata() {
  return new FileMetadata("/", 0, defaultPermissionNoBlobMetadata(),
      BlobMaterialization.Implicit);
}

private FileMetadata handleExistingBlob(CloudBlobWrapper blob) throws Exception {
  blob.downloadAttributes(getInstrumentedContext());
  BlobProperties properties = blob.getProperties();
  if (retrieveFolderAttribute(blob)) {
    return new FileMetadata(blob.getUri().toString(),
        properties.getLastModified().getTime(),
        getPermissionStatus(blob),
        BlobMaterialization.Explicit);
  } else {
    return new FileMetadata(blob.getUri().toString(),
        getDataLength(blob, properties),
        properties.getLastModified().getTime(),
        getPermissionStatus(blob));
  }
}

private FileMetadata handlePotentialDirectory(String key) throws Exception {
  Iterable<ListBlobItem> objects = listRootBlobs(key, true,
      EnumSet.of(BlobListingDetails.METADATA), null,
      getInstrumentedContext());
  for (ListBlobItem blobItem : objects) {
    if (blobItem instanceof CloudBlockBlobWrapper || blobItem instanceof CloudPageBlobWrapper) {
      CloudBlobWrapper blob = (CloudBlobWrapper) blobItem;
      BlobProperties properties = blob.getProperties();
      return new FileMetadata(key, properties.getLastModified().getTime(),
          getPermissionStatus(blob), BlobMaterialization.Implicit);
    }
  }
  return null;
}

